/**
 * @summary List results for a school
 */
export const getListResultsUrl = (
  schoolCode: string,
  params?: ListResultsParams,
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/schools/${schoolCode}/results?${stringifiedParams}`
    : `/api/schools/${schoolCode}/results`;
};

export const listResults = async (
  schoolCode: string,
  params?: ListResultsParams,
  options?: RequestInit,
): Promise<ExamResult[]> => {
  return customFetch<ExamResult[]>(getListResultsUrl(schoolCode, params), {
    ...options,
    method: "GET",
  });
};

export const getListResultsQueryKey = (
  schoolCode: string,
  params?: ListResultsParams,
) => {
  return [
    `/api/schools/${schoolCode}/results`,
    ...(params ? [params] : []),
  ] as const;
};

export const getListResultsQueryOptions = <
  TData = Awaited<ReturnType<typeof listResults>>,
  TError = ErrorType<unknown>,
>(
  schoolCode: string,
  params?: ListResultsParams,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof listResults>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
) => {
  const { query: queryOptions, request: requestOptions } = options ?? {};

  const queryKey =
    queryOptions?.queryKey ?? getListResultsQueryKey(schoolCode, params);

  const queryFn: QueryFunction<Awaited<ReturnType<typeof listResults>>> = ({
    signal,
  }) => listResults(schoolCode, params, { signal, ...requestOptions });

  return {
    queryKey,
    queryFn,
    enabled: !!schoolCode,
    ...queryOptions,
  } as UseQueryOptions<
    Awaited<ReturnType<typeof listResults>>,
    TError,
    TData
  > & { queryKey: QueryKey };
};

export type ListResultsQueryResult = NonNullable<
  Awaited<ReturnType<typeof listResults>>
>;
export type ListResultsQueryError = ErrorType<unknown>;

/**
 * @summary List results for a school
 */

export function useListResults<
  TData = Awaited<ReturnType<typeof listResults>>,
  TError = ErrorType<unknown>,
>(
  schoolCode: string,
  params?: ListResultsParams,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof listResults>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
): UseQueryResult<TData, TError> & { queryKey: QueryKey } {
  const queryOptions = getListResultsQueryOptions(schoolCode, params, options);

  const query = useQuery(queryOptions) as UseQueryResult<TData, TError> & {
    queryKey: QueryKey;
  };

  return { ...query, queryKey: queryOptions.queryKey };
}
